package workloadbalancingimpl

import (
	"encoding/json"
	"errors"
	"fmt"

	"github.com/DataDog/datadog-agent/pkg/remoteconfig/state"
)

// maxGroupIDLength bounds the group ID, which reaches a metric tag unmodified. Group IDs are
// generated by the backend and are far shorter than this in practice.
const maxGroupIDLength = 200

// groupCountWarnThreshold is the number of groups above which we say so once per update. Each
// group costs a time series on every Agent that knows about it, so an unexpected count is worth
// seeing in the logs before it is worth seeing on a bill.
const groupCountWarnThreshold = 500

var (
	errUnmarshal    = errors.New("error unmarshalling payload")
	errEmptyGroupID = errors.New("group_id is empty")
)

// parseAssignment decodes and validates one Remote Config payload.
func parseAssignment(raw []byte) (workloadBalancingRCConfig, error) {
	var msg workloadBalancingRCConfig
	if err := json.Unmarshal(raw, &msg); err != nil {
		return msg, fmt.Errorf("%w: %v", errUnmarshal, err)
	}
	if msg.GroupID == "" {
		return msg, errEmptyGroupID
	}
	if len(msg.GroupID) > maxGroupIDLength {
		return msg, fmt.Errorf("group_id is longer than %d characters", maxGroupIDLength)
	}
	return msg, nil
}

// onWorkloadBalancingUpdate applies a full set of group assignments. Remote Config sends every
// config that targets this Agent on every update, so the set we receive is authoritative and any
// group missing from it no longer has an assignment.
//
// An empty update therefore clears every group, which is the opposite of what the HA Agent does
// with one. HA stops running its checks when it loses its assignment; we keep running ours,
// because the failure we care about is a device nobody is polling.
func (w *workloadBalancingImpl) onWorkloadBalancingUpdate(updates map[string]state.RawConfig, applyStateCallback func(string, state.ApplyStatus)) {
	w.log.Debugf("Updates received: count=%d", len(updates))

	leaders := make(map[string]string, len(updates))
	applied := make(map[string]workloadBalancingRCConfig, len(updates))
	valid := make([]string, 0, len(updates))
	var invalid []string

	// First pass: every config we can parse. Map iteration is unordered, so a config we cannot
	// parse must not be allowed to write a group in the same loop, or it would sometimes overwrite
	// a fresh assignment for that group with a stale one.
	for configPath, rawConfig := range updates {
		w.log.Debugf("Received config %s: %s", configPath, string(rawConfig.Config))

		msg, err := parseAssignment(rawConfig.Config)
		if err != nil {
			w.log.Warnf("Skipping invalid NDM_AGENT_WORKLOAD_BALANCING update %s: %v", configPath, err)
			invalid = append(invalid, configPath)
			applyStateCallback(configPath, state.ApplyStatus{
				State: state.ApplyStateError,
				Error: applyStateError(err),
			})
			continue
		}

		leaders[msg.GroupID] = msg.ActiveAgent
		applied[configPath] = msg
		valid = append(valid, configPath)
		w.log.Debugf("Processed config %s: %v", configPath, msg)
	}

	// Second pass: carry the last assignment forward for the configs we could not parse, but only
	// for groups the first pass left untouched.
	if len(invalid) > 0 {
		previous := w.previousAssignments()
		for _, configPath := range invalid {
			w.keepPreviousAssignment(configPath, previous, leaders, applied)
		}
	}

	if len(leaders) > groupCountWarnThreshold {
		w.log.Warnf("Tracking %d workload balancing groups, above the expected %d", len(leaders), groupCountWarnThreshold)
	}

	if err := w.setGroupLeaders(leaders); err != nil {
		for _, configPath := range valid {
			applyStateCallback(configPath, state.ApplyStatus{
				State: state.ApplyStateError,
				Error: err.Error(),
			})
		}
		return
	}
	w.storeAssignments(applied)

	for _, configPath := range valid {
		applyStateCallback(configPath, state.ApplyStatus{
			State: state.ApplyStateAcknowledged,
		})
	}
}

// applyStateError keeps the Error we report to Remote Config stable, so a change in a JSON decoder
// message does not read as a different failure on the backend.
func applyStateError(err error) string {
	if errors.Is(err, errUnmarshal) {
		return errUnmarshal.Error()
	}
	return err.Error()
}

// keepPreviousAssignment carries the last assignment applied for configPath into this update. A
// config we cannot parse tells us nothing about its group, and dropping it would return that group
// to unmanaged and start this Agent polling a device another Agent already holds. A config we can
// parse always wins, so a group already set by this update is left alone.
func (w *workloadBalancingImpl) keepPreviousAssignment(configPath string, previous map[string]workloadBalancingRCConfig, leaders map[string]string, applied map[string]workloadBalancingRCConfig) {
	prev, ok := previous[configPath]
	if !ok {
		return
	}

	if _, claimed := leaders[prev.GroupID]; claimed {
		w.log.Infof("Ignoring the last assignment for %s: group %s was set by another config in this update", configPath, prev.GroupID)
		return
	}

	w.log.Infof("Keeping the last assignment for %s: group %s stays with %s", configPath, prev.GroupID, prev.ActiveAgent)
	leaders[prev.GroupID] = prev.ActiveAgent
	applied[configPath] = prev
}
